/** A custom attribute value. Each custom attribute value has a corresponding
`CustomAttributeDefinition` object. */
export type CustomAttribute = {
  "key"?: string;
  "value"?: Record<string, unknown>;
  "version"?: number;
  "visibility"?: CustomAttributeDefinitionVisibility;
  "definition"?: CustomAttributeDefinition;
  "updated_at"?: string;
  "created_at"?: string;
};

/** Represents a definition for custom attribute values. A custom attribute definition
specifies the key, visibility, schema, and other properties for a custom attribute. */
export type CustomAttributeDefinition = {
  "key"?: string;
  "schema"?: Record<string, unknown>;
  "name"?: string;
  "description"?: string;
  "visibility"?: CustomAttributeDefinitionVisibility;
  "version"?: number;
  "updated_at"?: string;
  "created_at"?: string;
};

/** Represents an object in the CustomAttributeDefinition event notification
payload that contains the affected custom attribute definition. */
export type CustomAttributeDefinitionEventData = {
  "type"?: string;
  "id"?: string;
  "object"?: CustomAttributeDefinitionEventDataObject;
};

export type CustomAttributeDefinitionEventDataObject = {
  "custom_attribute_definition"?: CustomAttributeDefinition;
};

/** The level of permission that a seller or other applications requires to
view this custom attribute definition.
The `Visibility` field controls who can read and write the custom attribute values
and custom attribute definition. */
export type CustomAttributeDefinitionVisibility = "VISIBILITY_HIDDEN" | "VISIBILITY_READ_ONLY" | "VISIBILITY_READ_WRITE_VALUES";

export type CustomAttributeEventData = {
  "type"?: string;
  "id"?: string;
  "object"?: CustomAttributeEventDataObject;
};

export type CustomAttributeEventDataObject = {
  "custom_attribute"?: CustomAttribute;
};

