/** Published when a [customer](entity:Customer) is created. Subscribe to this event to track customer profiles affected by a merge operation.
For more information, see [Use Customer Webhooks](https://developer.squareup.com/docs/customers-api/use-the-api/customer-webhooks).

The `customer` object in the event notification does not include the `segment_ids` field. */
export type CustomerCreatedEvent = {
  "merchant_id"?: string;
  "type"?: string;
  "event_id"?: string;
  "created_at"?: string;
  "data"?: CustomerCreatedEventData;
};

/** The data associated with the event. */
export type CustomerCreatedEventData = {
  "type"?: string;
  "id"?: string;
  "object"?: CustomerCreatedEventObject;
};

/** Information about the change that triggered the event. */
export type CustomerCreatedEventEventContext = {
  "merge"?: CustomerCreatedEventEventContextMerge;
};

/** Information about a merge operation, which creates a new customer using aggregated properties from two or more existing customers. */
export type CustomerCreatedEventEventContextMerge = {
  "from_customer_ids"?: Array<string>;
  "to_customer_id"?: string;
};

/** An object that contains the customer associated with the event. */
export type CustomerCreatedEventObject = {
  "customer"?: Customer;
  "event_context"?: CustomerCreatedEventEventContext;
};

/** Indicates the method used to create the customer profile. */
export type CustomerCreationSource = "OTHER" | "APPOINTMENTS" | "COUPON" | "DELETION_RECOVERY" | "DIRECTORY" | "EGIFTING" | "EMAIL_COLLECTION" | "FEEDBACK" | "IMPORT" | "INVOICES" | "LOYALTY" | "MARKETING" | "MERGE" | "ONLINE_STORE" | "INSTANT_PROFILE" | "TERMINAL" | "THIRD_PARTY" | "THIRD_PARTY_IMPORT" | "UNMERGE_RECOVERY";

/** The creation source filter.

If one or more creation sources are set, customer profiles are included in,
or excluded from, the result if they match at least one of the filter criteria. */
export type CustomerCreationSourceFilter = {
  "values"?: Array<CustomerCreationSource>;
  "rule"?: CustomerInclusionExclusion;
};

