  "total_price_money"?: V1Money;
  "total_discount_money"?: V1Money;
  "created_at"?: string;
  "updated_at"?: string;
  "expires_at"?: string;
  "payment_id"?: string;
  "buyer_note"?: string;
  "completed_note"?: string;
